    teaches: ["py.algo.in-place-arrays"],
    requires: [],
    difficulty: { concept: 4, implementation: 4, recall: 3 },
    estimatedMinutes: 12,
    prompt: "In-place algorithms survive by protecting information that has not been processed yet.\n\nRotate `values` left by `k` positions **in place** and return the same list object. `k` may be larger than the length.\n\n`([1, 2, 3, 4, 5], 2)` becomes `[3, 4, 5, 1, 2]`.\n\nThe triple-reversal trick does this with O(1) extra space: reverse the first `k`, reverse the rest, then reverse the whole list.",
    exportName: "rotate_left",
    scaffolds: { L1: "def rotate_left(values, k):\n    pass", L2: "def rotate_left(values, k):\n    pass", L3: "def rotate_left(values, k):\n    pass", L4: "" },
