      { name: "no clauses", code: "assert fn(2, []) is True", hidden: false },
      { name: "two variables satisfiable", code: "assert fn(2, [(0, 1), (-1, 1)]) is True", hidden: false },
      { name: "forced both ways", code: "assert fn(2, [(0, 0), (-1, -1), (1, 1)]) is False", hidden: true }
